  const canaryResults = runQueries(newAlgorithm, syntheticDataset);

  assert(latency(canaryResults) < latency(baselineResults) * 1.1);
  assert(errorRate(canaryResults) < 0.01);
  assert(qualityScore(canaryResults) >= qualityScore(baselineResults) * 0.95);
